// S3 Bucket Static Website Configuration properties
{
  "IndexDocument": "index.html",
  "ErrorDocument": "index.html" // Crucial for client-side routing fallback
}

// Example S3 Bucket policy restricting access to CloudFront OAC
{
  "Version": "2012-10-17",
  "Statement": {
    "Effect": "Allow",
    "Principal": { "Service": "cloudfront.amazonaws.com" },
    "Action": "s3:GetObject",
    "Resource": "arn:aws:s3:::my-spa-bucket/*",
    "Condition": {
      "StringEquals": {
        "AWS:SourceArn": "arn:aws:cloudfront::123456789012:distribution/ED12345EXAMPLE"
      }
    }
  }
}
